package com.distributedexam.server.monitoring; import com.distributedexam.common.*; import com.distributedexam.dao.*; import java.sql.Timestamp; import java.util.*;
public class IncidentManager { private final IncidentDAO dao; private final EventManager events; public IncidentManager(IncidentDAO d,EventManager e){dao=d;events=e;} public int report(Incident i)throws Exception{i.setStatus(i.getStatus()==null?"OPEN":i.getStatus());dao.create(i);ExamEvent e=new ExamEvent();e.setRoomId(i.getRoomId());e.setExamId(i.getExamId());e.setEventType("INCIDENT_REPORTED");e.setDescription(i.getDescription());events.log(e);return i.getIncidentId();} public boolean resolve(int id)throws Exception{Incident i=dao.findById(id);if(i==null)return false;i.setStatus("RESOLVED");i.setResolvedAt(new Timestamp(System.currentTimeMillis()));dao.update(i);return true;} public List<Incident> open()throws Exception{return dao.findOpen();} public List<Incident> room(int id)throws Exception{return dao.findByRoom(id);} }
